import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ListFilter, CalendarDays, Archive, Sparkles, X, ChevronDown, ChevronUp } from 'lucide-react';
import { generateMarketSummary } from './services/geminiService';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v3');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiSummary, setAiSummary] = useState('');
  const [showAiReport, setShowAiReport] = useState(false);

  useEffect(() => {
    localStorage.setItem('trading_journal_v3', JSON.stringify(insights));
  }, [insights]);

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        return { ...i, completionStatus: statuses[(currentIndex + 1) % statuses.length] };
      }
      return i;
    }));
  };

  const handleGenerateAI = async () => {
    if (insights.length === 0) return;
    setIsGeneratingAI(true);
    const summary = await generateMarketSummary(insights);
    setAiSummary(summary || "分析完成。");
    setIsGeneratingAI(false);
    setShowAiReport(true);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-red-100 selection:text-red-900 bg-[#fbfbfb]">
      {/* 极简顶栏 */}
      <header className="sticky top-0 z-[100] bg-white/70 backdrop-blur-2xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3">
              <div className="bg-gray-900 w-8 h-8 rounded-lg flex items-center justify-center shadow-lg shadow-gray-200">
                <LayoutGrid className="w-4 h-4 text-white" />
              </div>
              <h1 className="text-lg font-black text-gray-900 tracking-tighter">市场周刊</h1>
            </div>

            <nav className="hidden md:flex items-center gap-1 bg-gray-100/50 p-1 rounded-xl border border-gray-100">
              {CATEGORIES.slice(0, 4).map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-4 py-1.5 rounded-lg text-[13px] font-bold transition-all ${
                    activeCategory === cat ? 'bg-white text-gray-900 shadow-sm border border-gray-50' : 'text-gray-400 hover:text-gray-900'
                  }`}
                >
                  {cat}
                </button>
              ))}
              {CATEGORIES.length > 4 && (
                 <select 
                  className="bg-transparent text-[13px] font-bold text-gray-400 px-2 outline-none cursor-pointer"
                  value={CATEGORIES.includes(activeCategory) ? activeCategory : '全部'}
                  onChange={(e) => setActiveCategory(e.target.value as Category)}
                 >
                   <option value="全部">更多</option>
                   {CATEGORIES.slice(4).map(c => <option key={c} value={c}>{c}</option>)}
                 </select>
              )}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {/* YouMind 风格 AI 按钮 */}
            <button 
              onClick={handleGenerateAI}
              disabled={isGeneratingAI || insights.length === 0}
              className={`flex items-center gap-3 px-6 py-2.5 bg-[#12141c] text-white rounded-full transition-all active:scale-95 disabled:opacity-50 group shadow-[0_10px_30px_-5px_rgba(0,0,0,0.3)] hover:shadow-[0_15px_40px_-5px_rgba(0,0,0,0.4)] ${isGeneratingAI ? 'cursor-wait' : 'cursor-pointer'}`}
            >
              <Sparkles className={`w-4 h-4 text-amber-400 ${isGeneratingAI ? 'animate-spin' : 'group-hover:rotate-12'}`} />
              <span className="text-[13px] font-black tracking-tight">
                {isGeneratingAI ? '分析中...' : '获取 AI 智能周报'}
              </span>
            </button>

            <div className="w-[1px] h-6 bg-gray-100 mx-2" />

            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-red-500 text-white w-10 h-10 rounded-full flex items-center justify-center hover:bg-red-600 transition-all shadow-xl shadow-red-100 active:scale-90"
            >
              <Plus className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        {/* 左侧侧边栏：极简归档 */}
        <aside className="lg:w-48 space-y-10 flex-shrink-0">
          <div className="sticky top-[100px]">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6 ml-1">Archive</h3>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-[12px] font-bold transition-all flex items-center justify-between ${
                  selectedMonth === null ? 'bg-gray-900 text-white shadow-xl shadow-gray-200' : 'text-gray-400 hover:bg-gray-50'
                }`}
              >
                <span>所有时间</span>
                <span className="text-[10px] opacity-60">{insights.length}</span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-[12px] font-bold transition-all flex items-center justify-between ${
                    selectedMonth === month ? 'bg-gray-900 text-white shadow-xl shadow-gray-200' : 'text-gray-400 hover:bg-gray-50'
                  }`}
                >
                  <span>{month}</span>
                  <span className="text-[10px] opacity-60">{count}</span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* 主内容区 */}
        <main className="flex-grow">
          {/* AI 报告区：YouMind 风格深度分析卡片 */}
          {aiSummary && showAiReport && (
            <div className="mb-16 animate-in slide-in-from-top-8 duration-700 ease-out">
              <div className="bg-[#12141c] rounded-[3rem] p-10 md:p-14 text-white relative overflow-hidden shadow-[0_40px_100px_-20px_rgba(0,0,0,0.3)]">
                {/* 装饰元素 */}
                <div className="absolute top-0 right-0 w-96 h-96 bg-red-500/10 blur-[100px] -mr-48 -mt-48 rounded-full pointer-events-none" />

                <div className="relative z-10">
                  <div className="flex items-center justify-between mb-12">
                    <div className="flex items-center gap-3">
                      <div className="p-2.5 bg-amber-400/10 rounded-xl border border-amber-400/20">
                        <Sparkles className="w-5 h-5 text-amber-400" />
                      </div>
                      <div>
                        <h2 className="text-xl font-black tracking-tight">AI 深度研判周报</h2>
                        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-0.5">Automated Intelligence Report</p>
                      </div>
                    </div>
                    <button 
                      onClick={() => setShowAiReport(false)}
                      className="p-2 hover:bg-white/10 rounded-full transition-colors text-gray-400"
                    >
                      <X className="w-5 h-5" />
                    </button>
                  </div>

                  <div className="max-w-4xl">
                    <div className="text-lg md:text-xl font-medium leading-[1.8] text-gray-100 whitespace-pre-wrap selection:bg-amber-400 selection:text-black">
                      {aiSummary}
                    </div>
                  </div>

                  <div className="mt-12 pt-10 border-t border-white/5 flex flex-wrap gap-8 text-[11px] font-bold text-gray-500 uppercase tracking-widest">
                    <div className="flex items-center gap-2">
                       <div className="w-1.5 h-1.5 bg-red-500 rounded-full" />
                       分析时间：{new Date().toLocaleDateString()}
                    </div>
                    <div className="flex items-center gap-2">
                       <div className="w-1.5 h-1.5 bg-amber-400 rounded-full" />
                       分析样本：{insights.length} 条记录
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {!showAiReport && aiSummary && (
             <button 
              onClick={() => setShowAiReport(true)}
              className="mb-12 w-full flex items-center justify-center gap-2 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-[12px] font-black text-gray-400 hover:bg-white hover:shadow-lg transition-all"
             >
                <ChevronDown className="w-4 h-4" />
                展开最近一次 AI 智能研判
             </button>
          )}

          {/* 标题与过滤器 */}
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <div className="space-y-3">
              <h2 className="text-4xl md:text-5xl font-black text-gray-900 tracking-tighter leading-tight italic">
                捕捉市场的<br />每一丝脉动。
              </h2>
            </div>

            <div className="flex bg-gray-100/50 p-1 rounded-xl items-center border border-gray-100 self-start md:self-end">
              <button onClick={() => setSortMode('category')} className={`px-5 py-2 rounded-lg text-[11px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm border border-gray-50' : 'text-gray-400 hover:text-gray-600'}`}>
                <ListFilter className="w-3 h-3 mr-1.5 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-5 py-2 rounded-lg text-[11px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm border border-gray-50' : 'text-gray-400 hover:text-gray-600'}`}>
                <CalendarDays className="w-3 h-3 mr-1.5 inline" /> 时间
              </button>
            </div>
          </div>

          {/* 记录列表 */}
          {activeItems.length > 0 ? (
            <div className="space-y-12">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel}>
                  <div className="flex items-center gap-4 mb-10">
                    <div className="bg-[#12141c] text-white px-5 py-1.5 rounded-full shadow-xl shadow-gray-200">
                       <span className="text-[12px] font-black tracking-widest uppercase">{groupLabel}</span>
                    </div>
                    <div className="flex-grow h-[1px] bg-gray-100" />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-32 bg-white rounded-[3rem] border border-dashed border-gray-200 shadow-sm">
              <Plus className="w-10 h-10 text-gray-200 mx-auto mb-4" />
              <h3 className="text-xl font-black text-gray-900 mb-1">开始你的第一份记录</h3>
              <p className="text-xs text-gray-400">点击右上角的按钮添加市场观察</p>
            </div>
          )}

          {/* 已归档历史 */}
          {archivedItems.length > 0 && (
            <div className="mt-40">
               <div className="flex items-center gap-6 mb-12 opacity-30 grayscale">
                  <Archive className="w-6 h-6" />
                  <h3 className="text-xl font-black tracking-tight">已完成的历史归档</h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto py-16 border-t border-gray-100 text-center">
          <p className="text-[10px] text-gray-300 font-black uppercase tracking-[0.5em]">Trading Journal Pro · v3.0</p>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, TrendingUp, TrendingDown, Activity, Target } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-red-50 text-red-600 border-red-100',
      accent: 'bg-red-50/30 border-red-200 text-red-900',
      icon: <TrendingUp className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-green-50 text-green-600 border-green-100',
      accent: 'bg-green-50/30 border-green-200 text-green-900',
      icon: <TrendingDown className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-blue-50 text-blue-600 border-blue-100',
      accent: 'bg-blue-50/30 border-blue-200 text-blue-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-gray-50 text-gray-500 border-gray-100',
      accent: 'bg-gray-50/30 border-gray-200 text-gray-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const completionStatus = insight.completionStatus;
  const { color, icon, accent } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-white border-emerald-100 shadow-sm opacity-80';
      case '已失效': return 'bg-[#fafafa] border-slate-200 opacity-50 grayscale';
      default: return 'bg-white border-gray-100 shadow-[0_4px_24px_-4px_rgba(0,0,0,0.04)] hover:shadow-[0_32px_64px_-16px_rgba(0,0,0,0.08)] hover:-translate-y-1';
    }
  };

  const getTagStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-500 text-white'; 
      case '已失效': return 'bg-slate-500 text-white'; 
      default: return 'bg-red-500 text-white';
    }
  };

  return (
    <div className={`group relative mt-4 border rounded-[2rem] p-8 pt-10 transition-all duration-500 flex flex-col min-h-[400px] ${getCardStyle()}`}>

      {/* 状态标签 */}
      <div className="absolute -top-3 left-8 z-30">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg transition-all active:scale-95 hover:brightness-110 ${getTagStyle()}`}
        >
          {completionStatus}
        </button>
      </div>

      <div className="relative z-10 flex justify-between items-start mb-8">
        <div>
          <h3 className="text-2xl font-black text-gray-900 tracking-tighter mb-1">{insight.symbol}</h3>
          <div className="flex items-center text-[10px] text-gray-400 gap-1.5 font-bold uppercase tracking-widest">
            <Calendar className="w-3 h-3 opacity-40" />
            {date}
          </div>
        </div>
        <div className={`px-3 py-1.5 rounded-xl text-[11px] font-black border flex items-center gap-2 ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      <div className="relative z-10 space-y-6 flex-grow">
        <div className="space-y-2">
          <p className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-300">Observation</p>
          <p className="text-[14px] leading-relaxed font-medium text-gray-700">
            {insight.focusPoints}
          </p>
        </div>

        {insight.entryLevel && (
          <div className="flex items-center justify-between p-4 rounded-2xl bg-gray-50/50 border border-gray-100">
            <p className="text-[9px] font-black uppercase tracking-widest text-gray-400">Entry</p>
            <div className="flex items-center gap-2">
              <Target className="w-3 h-3 text-red-400" />
              <p className="text-sm font-black text-gray-900">{insight.entryLevel}</p>
            </div>
          </div>
        )}

        <div className={`p-5 rounded-2xl border-l-4 transition-all ${completionStatus === '进行中' ? accent : 'bg-gray-50 border-gray-200'}`}>
          <p className="text-[9px] font-black uppercase tracking-[0.2em] opacity-40 mb-2">Strategy</p>
          <p className={`text-[14px] font-bold leading-relaxed ${completionStatus === '进行中' ? 'text-gray-900' : 'text-gray-400'}`}>
            {insight.strategy}
          </p>
        </div>
      </div>

      {/* 控制按钮 */}
      <div className="relative z-10 mt-8 pt-6 border-t border-gray-100/60 flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all duration-300">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-lg transition-all"
        >
          <Edit2 className="w-4 h-4" />
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
        >
          <Trash2 className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
};

